export function wrapPredicate(
	data: T.Predicate & { readonly _pound?: '#' | '.'; readonly _dot?: '#' | '.' },
	tree: TreeHandle
) {
	data = _keepModelledSlots(data, ['_content', '_immediate_identifier', '_type', '_parameters', '_pound', '_dot']);
	if (_isReadTextLeaf(data)) return withMethods({ ...data, $type: TSKindId.Predicate as const }, _treeEngine(tree));
	const _node = withMethods(
		{
			..._omitWrapKeys(data, ['_dot', '_pound']),
			$type: TSKindId.Predicate as const,
			_content: projectKindEnumStorage(
				normalizeSingularWrapSlot(
					data._content ?? data._pound ?? data._dot ?? readTerminalFromOther(data, [TSKindId.Pound, TSKindId.Dot]),
					'content',
					true,
					data.$type,
					{ tree, nodeType: data.$type, slotName: 'content', span: (data as _NodeData).$span }
				),
				{ '#': 20, '.': 21 }
			),
			_immediate_identifier: normalizeSingularWrapSlot(
				data._immediate_identifier,
				'immediate_identifier',
				true,
				data.$type,
				{ tree, nodeType: data.$type, slotName: 'immediate_identifier', span: (data as _NodeData).$span }
			),
			_type: projectKindEnumStorage(
				normalizeSingularWrapSlot(
					data._type ?? readTerminalFromOther(data, [TSKindId.Qmark, TSKindId.Bang]),
					'type',
					true,
					data.$type,
					{ tree, nodeType: data.$type, slotName: 'type', span: (data as _NodeData).$span }
				),
				{ '?': 4, '!': 19 }
			),
			_parameters: normalizeSingularWrapSlot(data._parameters, 'parameters', false, data.$type, {
				tree,
				nodeType: data.$type,
				slotName: 'parameters',
				span: (data as _NodeData).$span
			}),

			content() {
				return this._content;
			},
			immediateIdentifier() {
				return drillIn<T.ImmediateIdentifier>(this._immediate_identifier, tree);
			},
			type() {
				return this._type;
			},
			parameters() {
				return drillIn<T.Parameters | undefined>(this._parameters, tree);
			},
			$with: {
				content: (v: NonNullable<T.Predicate['_content']>) => wrapPredicate({ ...$edited(data), _content: v }, tree),
				immediateIdentifier: (v: NonNullable<T.Predicate['_immediate_identifier']>) =>
					wrapPredicate({ ...$edited(data), _immediate_identifier: v }, tree),
				type: (v: NonNullable<T.Predicate['_type']>) => wrapPredicate({ ...$edited(data), _type: v }, tree),
				parameters: (v: NonNullable<T.Predicate['_parameters']>) =>
					wrapPredicate({ ...$edited(data), _parameters: v }, tree)
			}
		},
		_treeEngine(tree)
	);
	return _node;
}

