const _wrapTable: Record<number, (data: _NodeData, tree: TreeHandle) => unknown> = {
	[TSKindId.Program]: (d, t) => wrapProgram(d as unknown as T.Program, t),
	[TSKindId.Definition]: (d, t) => wrapDefinition(d as unknown as T.Definition, t),
	[TSKindId.GroupExpression]: (d, t) => wrapGroupExpression(d as unknown as T.GroupExpression, t),
	[TSKindId.NamedNodeExpression]: (d, t) => wrapNamedNodeExpression(d as unknown as T.NamedNodeExpression, t),
	[TSKindId.EscapeSequence]: (d, t) => wrapEscapeSequence(d as unknown as T.EscapeSequence, t),
	[TSKindId.Quantifier]: (d) => ({ ...d, $type: TSKindId.Quantifier as const }),
	[TSKindId.Identifier]: (d) => ({ ...d, $type: TSKindId.Identifier as const }),
	[TSKindId.ImmediateIdentifier]: (d) => ({ ...d, $type: TSKindId.ImmediateIdentifier as const }),
	[TSKindId.NodeIdentifier]: (d, t) => wrapNodeIdentifier(d as unknown as T.NodeIdentifier, t),
	[TSKindId.Capture]: (d, t) => wrapCapture(d as unknown as T.Capture, t),
	[TSKindId.String]: (d, t) => wrapString(d as unknown as T.String, t),
	[TSKindId.ImmediateString]: (d, t) => wrapImmediateString(d as unknown as T.ImmediateString, t),
	[TSKindId.StringContent]: (d, t) => wrapStringContent(d as unknown as T.StringContent, t),
	[TSKindId.Parameters]: (d, t) => wrapParameters(d as unknown as T.Parameters, t),
	[TSKindId.Comment]: (d, t) => wrapComment(d as unknown as T.Comment, t),
	[TSKindId.List]: (d, t) => wrapList(d as unknown as T.List, t),
	[TSKindId.Grouping]: (d, t) => wrapGrouping(d as unknown as T.Grouping, t),
	[TSKindId.MissingNode]: (d, t) => wrapMissingNode(d as unknown as T.MissingNode, t),
	[TSKindId.AnonymousNode]: (d, t) => wrapAnonymousNode(d as unknown as T.AnonymousNode, t),
	[TSKindId.NamedNode]: (d, t) => wrapNamedNode(d as unknown as T.NamedNode, t),
	[TSKindId.FieldDefinition]: (d, t) => wrapFieldDefinition(d as unknown as T.FieldDefinition, t),
	[TSKindId.NegatedField]: (d, t) => wrapNegatedField(d as unknown as T.NegatedField, t),
	[TSKindId.Predicate]: (d, t) => wrapPredicate(d as unknown as T.Predicate, t),
	[TSKindId.PredicateType]: (d) => ({ ...d, $type: TSKindId.PredicateType as const }),
	[TSKindId.GroupExpressionArm]: (d, t) => wrapGroupExpressionArm(d as unknown as T.GroupExpressionArm, t),
	[TSKindId.NamedNodeExpressionArm]: (d, t) => wrapNamedNodeExpressionArm(d as unknown as T.NamedNodeExpressionArm, t),
	[TSKindId.GroupingGroup]: (d, t) => wrapGroupingGroup(d as unknown as T.GroupingGroup, t),
	[TSKindId.NamedNodeArm]: (d, t) => wrapNamedNodeArm(d as unknown as T.NamedNodeArm, t),
	[TSKindId.NamedNodeGroup]: (d, t) => wrapNamedNodeGroup(d as unknown as T.NamedNodeGroup, t),
	[TSKindId.NamedNodeGroupChildren]: (d, t) => wrapNamedNodeGroupChildren(d as unknown as T.NamedNodeGroupChildren, t),
	[TSKindId.NamedNodeGroupAnchoredLast]: (d, t) =>
		wrapNamedNodeGroupAnchoredLast(d as unknown as T.NamedNodeGroupAnchoredLast, t)
};

interface _WrapReturnByKindId {
	[TSKindId.Program]: ReturnType<typeof wrapProgram>;
	[TSKindId.Definition]: ReturnType<typeof wrapDefinition>;
	[TSKindId.GroupExpression]: ReturnType<typeof wrapGroupExpression>;
	[TSKindId.NamedNodeExpression]: ReturnType<typeof wrapNamedNodeExpression>;
	[TSKindId.EscapeSequence]: ReturnType<typeof wrapEscapeSequence>;
	[TSKindId.Quantifier]: _NodeData & { readonly $type: TSKindId.Quantifier };
	[TSKindId.Identifier]: _NodeData & { readonly $type: TSKindId.Identifier };
	[TSKindId.ImmediateIdentifier]: _NodeData & { readonly $type: TSKindId.ImmediateIdentifier };
	[TSKindId.NodeIdentifier]: ReturnType<typeof wrapNodeIdentifier>;
	[TSKindId.Capture]: ReturnType<typeof wrapCapture>;
	[TSKindId.String]: ReturnType<typeof wrapString>;
	[TSKindId.ImmediateString]: ReturnType<typeof wrapImmediateString>;
	[TSKindId.StringContent]: ReturnType<typeof wrapStringContent>;
	[TSKindId.Parameters]: ReturnType<typeof wrapParameters>;
	[TSKindId.Comment]: ReturnType<typeof wrapComment>;
	[TSKindId.List]: ReturnType<typeof wrapList>;
	[TSKindId.Grouping]: ReturnType<typeof wrapGrouping>;
	[TSKindId.MissingNode]: ReturnType<typeof wrapMissingNode>;
	[TSKindId.AnonymousNode]: ReturnType<typeof wrapAnonymousNode>;
	[TSKindId.NamedNode]: ReturnType<typeof wrapNamedNode>;
	[TSKindId.FieldDefinition]: ReturnType<typeof wrapFieldDefinition>;
	[TSKindId.NegatedField]: ReturnType<typeof wrapNegatedField>;
	[TSKindId.Predicate]: ReturnType<typeof wrapPredicate>;
	[TSKindId.PredicateType]: _NodeData & { readonly $type: TSKindId.PredicateType };
	[TSKindId.GroupExpressionArm]: ReturnType<typeof wrapGroupExpressionArm>;
	[TSKindId.NamedNodeExpressionArm]: ReturnType<typeof wrapNamedNodeExpressionArm>;
	[TSKindId.GroupingGroup]: ReturnType<typeof wrapGroupingGroup>;
	[TSKindId.NamedNodeArm]: ReturnType<typeof wrapNamedNodeArm>;
	[TSKindId.NamedNodeGroup]: ReturnType<typeof wrapNamedNodeGroup>;
	[TSKindId.NamedNodeGroupChildren]: ReturnType<typeof wrapNamedNodeGroupChildren>;
	[TSKindId.NamedNodeGroupAnchoredLast]: ReturnType<typeof wrapNamedNodeGroupAnchoredLast>;
}

/** The wrapped root of a whole-source parse — what `engine.parse()` returns. */
export type ProgramTree = _WrapReturnByKindId[TSKindId.Program] & ParsedRoot;

function _drillUnknownKindChildren(data: _NodeData, tree: TreeHandle): _NodeData {
	const out: Record<string, unknown> = { ...(data as unknown as Record<string, unknown>) };
	for (const key of Object.keys(out)) {
		if (key.charCodeAt(0) !== 95 /* `_` */) continue;
		const value = out[key];
		if (Array.isArray(value)) {
			out[key] = drillInAll(value, tree);
		} else if (value != null) {
			out[key] = drillIn(value, tree);
		}
	}
	return out as unknown as _NodeData;
}

/** Wrap a NodeData into its lazy read-only view. */
export function wrapNode<T extends _NodeData & { readonly $type: keyof _WrapReturnByKindId }>(
	data: T,
	tree: TreeHandle
): _WrapReturnByKindId[T['$type'] & keyof _WrapReturnByKindId] & Pick<T, Extract<keyof T, keyof ParsedRoot>>;
export function wrapNode(data: _NodeData, tree: TreeHandle): unknown;
export function wrapNode(data: _NodeData, tree: TreeHandle): unknown {
	// The wire `$type` is the numeric grammar-symbol KindId — dispatch
	// is a direct id-keyed lookup. A non-numeric `$type` can only be a
	// catalog-less kind (the deprecated JS diagnostic lane stamps those
	// as strings), which never had a table entry to reach.
	const fn = typeof data.$type === 'number' ? _wrapTable[data.$type] : undefined;
	if (!fn) return _drillUnknownKindChildren(data, tree); // unknown kind — still drill in its kind-named-slot children
	return fn(data, tree);
}

/**
 * Per-handle dispatching `readNode` — the architectural seam where
 * the engine choice (JS vs native) lives. `readTreeNode`,
 * and `drillIn` read through THIS function so the
 * wrap layer is engine-agnostic. tree-sitter `Node::id()` is
 * documented as "unique within a given syntax tree" and is a
 * raw pointer cast — different parses yield different ids — so
 * the engine that parsed the tree is the only thing that can
 * dereference its ids. Native handles set `tree.read` to a
 * closure that routes through napi; wasm/JS handles (used by
 * retained diagnostic tooling — `tool walk`, `tool probe-kind
 * --engine js`) leave it absent and fall back to `readNodeJs`
 * (the in-process walker).
 */
function readNode(tree: TreeHandle, handle?: number, childIndex?: number): AnyNodeData {
	// Per-handle dispatch: native-engine handles carry a `read`
	// closure that routes through napi (engine owns the tree;
	// navigation via handle + childIndex replaces nodeId).
	// Wasm/JS handles (retained diagnostic tooling) leave `read`
	// absent and fall back to the in-process JS walker.
	return tree.read ? tree.read(handle, childIndex) : readNodeJs(tree, handle, childIndex);
}

/**
 * Read a parsed tree node into a lazily-wrapped NodeData.
 * One level deep — getters drill into subtrees on demand by
 * recursing back through this same function. The wire `$type` is
 * the grammar symbol (stamped by the read), so no per-site alias
 * rewriting exists between the read and the wrap.
 */
export function readTreeNode(tree: TreeHandle, handle?: number, childIndex?: number): unknown {
	return wrapNode(readNode(tree, handle, childIndex), tree);
}
